class EntryPoint extends StatefulWidget { const EntryPoint({super.key}); @override State<EntryPoint> createState() => _EntryPointState(); }
class _EntryPointState extends State<EntryPoint> {
  final store = LocalStore();
  HealthProfile? profile;
  DayLog log = DayLog();
  List<GroceryItem> groceries = [];
  bool signedIn = false;
  @override void initState() { super.initState(); load(); }
  Future<void> load() async { final loadedProfile = await store.loadProfile(); final loadedLog = await store.loadLog(); final loadedGroceries = await store.loadGroceries(); if (mounted) setState(() { profile = loadedProfile; log = loadedLog; groceries = loadedGroceries; }); }
  @override Widget build(BuildContext context) => profile == null ? const Scaffold(body: Center(child: CircularProgressIndicator())) : signedIn ? Shell(profile: profile!, log: log, groceries: groceries, store: store, onChanged: () => setState(() {})) : AuthPage(onContinue: () => setState(() => signedIn = true));
}

